<node CREATED="1280795096373" ID="Freemind_Link_241206519" MODIFIED="1280795119885" TEXT="Secretar&#xed;as, tenedores de libros u oficinistas"/>
<node CREATED="1280794933133" ID="Freemind_Link_1837015005" MODIFIED="1280794986045" TEXT="Personas como secretar&#xed;as o tenedores de libros que procesan el trabajo de oficina de la organizaci&#xf3;n"/>
</node>
<node CREATED="1280795002703" FOLDED="true" ID="Freemind_Link_1291984608" MODIFIED="1390920008912" TEXT="Trabajadores de producci&#xf3;n o servicios">
<node CREATED="1280795028443" ID="Freemind_Link_1065232228" MODIFIED="1280795053515" TEXT="Maquinistas, ensambladores o empacadores"/>
<node CREATED="1280795054493" ID="Freemind_Link_1067891782" MODIFIED="1280795091425" TEXT="Las personas que elaboran en realidad los productos o servicios de la organizaci&#xf3;n"/>
</node>
<node CREATED="1280795173513" FOLDED="true" ID="Freemind_Link_489258311" MODIFIED="1280795255565" TEXT="Cada organizaci&#xf3;n tiene una cultura especial o conjunto fundamental de supuestos, valores y formas de hacer las cosas, que ha sido aceptado por la mayor&#xed;a de sus integrantes">
<node CREATED="1280795259543" ID="Freemind_Link_1064938959" MODIFIED="1280795301105" TEXT="Partes de la cultura de una organizaci&#xf3;n se pueden encontrar siempre incorporadas en sus sistemas de informaci&#xf3;n"/>
</node>
<node CREATED="1280795325613" FOLDED="true" ID="Freemind_Link_1887667761" MODIFIED="1390920008913" TEXT="Los diversos niveles y especialidades de una organizaci&#xf3;n crean intereses y puntos de vista diferentes">
<node CREATED="1280795394123" ID="Freemind_Link_1769736695" MODIFIED="1280795416925" TEXT="Con frecuencia estos puntos de vista crean conflictos"/>
<node CREATED="1280795417603" ID="Freemind_Link_86424257" MODIFIED="1280795441265" TEXT="El conflicto es la base de las pol&#xed;ticas de una organizaci&#xf3;n"/>
</node>
</node>
<node CREATED="1280795515785" FOLDED="true" ID="Freemind_Link_1917052122" MODIFIED="1280800326812" TEXT="Administraci&#xf3;n">
<node CREATED="1280795591251" ID="Freemind_Link_463074170" MODIFIED="1280796036445" TEXT="El trabajo de la administraci&#xf3;n es darle sentido a las diversas situaciones que enfrentan las organizaciones, tomar decisiones y formular planes de acci&#xf3;n para resolver problemas de la organizaci&#xf3;n"/>
<node CREATED="1280796051318" FOLDED="true" ID="Freemind_Link_864711001" MODIFIED="1280796104890" TEXT="Los gerentes perciben los retos de negocios en el entorno, establecen la estrategia y coordinar el trabajo">
<node CREATED="1280796108157" ID="Freemind_Link_1723068574" MODIFIED="1280796140856" TEXT="Deben ejercer un liderazgo responsable de principio a fin"/>
<node CREATED="1280796213098" ID="Freemind_Link_615180917" MODIFIED="1280796258028" TEXT="Deben crear nuevos productos y servicios e incluso recrear la organizaci&#xf3;n de vez en cuando"/>
<node CREATED="1280796276535" ID="Freemind_Link_739569365" MODIFIED="1280796335271" TEXT="La responsabilidad de la administraci&#xf3;n es el trabajo creativo impulsado por el nuevo conocimiento y la nueva informaci&#xf3;n"/>
</node>
<node CREATED="1280796151049" ID="Freemind_Link_572200000" MODIFIED="1280796200050" TEXT="Los sistemas de informaci&#xf3;n reflejan las esperanzas, sue&#xf1;os y realidades de los gerentes del mundo real"/>
<node CREATED="1280796352702" ID="Freemind_Link_466773903" MODIFIED="1280796413232" TEXT="La tecnolog&#xed;a de la informaci&#xf3;n puede jugar un papel preponderante en la redirecci&#xf3;n y redise&#xf1;o de la organizaci&#xf3;n"/>
<node CREATED="1280796443518" ID="Freemind_Link_382035561" MODIFIED="1280796482738" TEXT="Los roles gerenciales y las decisiones var&#xed;an en los diferentes niveles de la organizaci&#xf3;n"/>
<node CREATED="1280796488984" FOLDED="true" ID="Freemind_Link_688309783" MODIFIED="1280796493993" TEXT="Directores">
<node CREATED="1280796494748" ID="Freemind_Link_1613290382" MODIFIED="1280796538180" TEXT="Personas que ocupan los puestos m&#xe1;s altos de la jerarqu&#xed;a en una organizaci&#xf3;n y que son las responsables de tomar decisiones a largo plazo"/>
</node>
<node CREATED="1280796548545" FOLDED="true" ID="Freemind_Link_1100922159" MODIFIED="1280796553960" TEXT="Gerentes de nivel medio">
<node CREATED="1280796554839" ID="Freemind_Link_143402950" MODIFIED="1280796611820" TEXT="Personas que est&#xe1;n a media jerarqu&#xed;a organizacional y que son responsables de llevar a cabo los planes y objetivos de la direcci&#xf3;n general"/>
</node>
<node CREATED="1280796616412" FOLDED="true" ID="Freemind_Link_1084020090" MODIFIED="1280796622670" TEXT="Gerentes operativos">
<node CREATED="1280796623300" ID="Freemind_Link_202357413" MODIFIED="1280796642427" TEXT="Personas que supervisan las actividades diarias de la organizaci&#xf3;n"/>
</node>
<node CREATED="1280796649313" FOLDED="true" ID="Freemind_Link_1169505880" MODIFIED="1280796657084" TEXT="Hardware de c&#xf3;mputo">
<node CREATED="1280796657729" ID="Freemind_Link_1182583558" MODIFIED="1280796704937" TEXT="Es el equipo f&#xed;sico utilizado para las actividades de introducir, procesar y dar salida en un sistema de informaci&#xf3;n"/>
</node>
<node CREATED="1280796728155" FOLDED="true" ID="Freemind_Link_447806291" MODIFIED="1280796735957" TEXT="Software de c&#xf3;mputo">
<node CREATED="1280796736727" ID="Freemind_Link_1643630931" MODIFIED="1280849575474" TEXT="Instrucciones detalladas preprogramadas que controlan y coordinan los componentes del hardware de c&#xf3;mputo en un sistema de informaci&#xf3;n"/>
</node>
<node CREATED="1280796794252" FOLDED="true" ID="Freemind_Link_1813841695" MODIFIED="1280796804441" TEXT="Tecnolog&#xed;a de almacenamiento">
<node CREATED="1280796805617" ID="Freemind_Link_968672099" MODIFIED="1280796862543" TEXT="Medios f&#xed;sicos y software que gobiernan el almacenamiento y organizaci&#xf3;n de datos para su uso en un sistema de informaci&#xf3;n"/>
</node>
<node CREATED="1280796867666" FOLDED="true" ID="Freemind_Link_1279233375" MODIFIED="1280796879602" TEXT="Tecnolog&#xed;a de comunicaciones">
<node CREATED="1280796883274" ID="Freemind_Link_1022137960" MODIFIED="1280796931885" TEXT="Dispositivos f&#xed;sicos y software que enlazan varios componentes del hardware de c&#xf3;mputo y que transfieren datos de una ubicaci&#xf3;n f&#xed;sica a otra"/>
</node>
<node CREATED="1280796947148" FOLDED="true" ID="Freemind_Link_1422364481" MODIFIED="1280796950098" TEXT="Red">
<node CREATED="1280796950947" ID="Freemind_Link_1917747736" MODIFIED="1280796984301" TEXT="El v&#xed;nculo de dos o m&#xe1;s computadoras para compartir datos o recursos, como una impresora"/>
</node>
<node CREATED="1280796988956" FOLDED="true" ID="Freemind_Link_862915240" MODIFIED="1280797009020" TEXT="Infraestructura de Tecnolog&#xed;a de la Informaci&#xf3;n (TI)">
<node CREATED="1280797010367" ID="Freemind_Link_1800521476" MODIFIED="1280797075249" TEXT="Tecnolog&#xed;a de hardware y software de c&#xf3;mputo, de datos y almacenamiento, y redes que proveen una cartera de recursos compartidos de tecnolog&#xed;a de la informaci&#xf3;n para la organizaci&#xf3;n"/>
</node>
</node>
</node>
</node>
<node CREATED="1280797178730" FOLDED="true" ID="Freemind_Link_1295741576" MODIFIED="1390920008934" TEXT="Enfoques contempor&#xe1;neos de los sistemas de informaci&#xf3;n">
<icon BUILTIN="full-2"/>
<node CREATED="1280797237456" ID="Freemind_Link_1159568837" MODIFIED="1280797276084" TEXT="El estudio de los sistemas de la infomaci&#xf3;n constituye un campo multidisciplinario"/>
<node CREATED="1280797286510" ID="Freemind_Link_1132505058" MODIFIED="1280797302019" TEXT="No hay teor&#xed;a o perspectiva que domine sola"/>
<node CREATED="1280797342678" FOLDED="true" ID="Freemind_Link_1274551684" MODIFIED="1390920008931" TEXT="Se puede dividir:">
<node CREATED="1280797371998" FOLDED="true" ID="Freemind_Link_1088485782" MODIFIED="1390920008929" TEXT="Enfoque t&#xe9;cnico">
<node CREATED="1280797398144" ID="Freemind_Link_688471646" MODIFIED="1280797477199" TEXT="Pone en relieve los modelos basados matem&#xe1;ticamente para estudiar los sistemas de la informaci&#xf3;n, as&#xed; como la tecnolog&#xed;a f&#xed;sica y las capacidades formales de estos sistemas"/>
<node CREATED="1280797489466" FOLDED="true" ID="Freemind_Link_1786752932" MODIFIED="1390920008927" TEXT="Las disciplinas que contribuyen al enfoque t&#xe9;cnico son:">
<node CREATED="1280797524231" FOLDED="true" ID="Freemind_Link_1774796386" MODIFIED="1390920008915" TEXT="Ciencias de la computaci&#xf3;n">
<node CREATED="1280797589642" ID="Freemind_Link_1150793595" MODIFIED="1280797659891" TEXT="Tienen que ver con el establecimiento de teor&#xed;as de computaci&#xf3;n, m&#xe9;todos de c&#xe1;lculo y m&#xe9;todos eficientes de almacenamiento y acceso a datos"/>
</node>
<node CREATED="1280797539823" FOLDED="true" ID="Freemind_Link_397241521" MODIFIED="1390920008917" TEXT="Ciencias de la administraci&#xf3;n">
<node CREATED="1280797684669" ID="Freemind_Link_900824430" MODIFIED="1280797730504" TEXT="Destacan el desarrollo de modelos para toma de decisiones y pr&#xe1;cticas administrativas"/>
</node>
<node CREATED="1280797556164" FOLDED="true" ID="Freemind_Link_1931986303" MODIFIED="1390920008919" TEXT="Investigaci&#xf3;n de operaciones">
<node CREATED="1280797738762" ID="Freemind_Link_81890902" MODIFIED="1280797810774" TEXT="Se enfoca en t&#xe9;cnicas matem&#xe1;ticas para optimizar par&#xe1;metros seleccionados de organizaciones como transporte, control de inventarios y costos de transacciones"/>
</node>
</node>
</node>
<node CREATED="1280797381070" FOLDED="true" ID="Freemind_Link_745666041" MODIFIED="1280797387203" TEXT="Enfoque conductual">
<node CREATED="1280797870933" ID="Freemind_Link_539023170" MODIFIED="1280797941806" TEXT="Una parte importante del campo de los sistemas de informaci&#xf3;n concierne a aspectos de conducta que surgen en el desarrollo y mantenimiento a largo plazo de los sistemas de informaci&#xf3;n"/>
<node CREATED="1280798222815" ID="Freemind_Link_1360696380" MODIFIED="1280798301846" TEXT="Aspectos como la integraci&#xf3;n estrat&#xe9;gica de la empresa, dise&#xf1;o, implementaci&#xf3;n, uso y administraci&#xf3;n no se pueden explorar con &#xe9;xito utilizando los modelos que se aplicaron en el enfoque t&#xe9;cnico"/>
<node CREATED="1280798320322" FOLDED="true" ID="Freemind_Link_725312662" MODIFIED="1280798344738" TEXT="Otras disciplinas aportan m&#xe9;todos y conceptos importantes">
<node CREATED="1280798345758" FOLDED="true" ID="Freemind_Link_810567112" MODIFIED="1280798358537" TEXT="Sociolog&#xed;a">
<node CREATED="1280798361101" ID="Freemind_Link_1663676373" MODIFIED="1280798442426" TEXT="Estudia los sistemas de informaci&#xf3;n analizando la manera en que los grupos y las organizaciones dan forma al desarrollo de los sistemas y c&#xf3;mo &#xe9;stos afectan a los individuos"/>
</node>
<node CREATED="1280798459623" FOLDED="true" ID="Freemind_Link_1548387085" MODIFIED="1280798463696" TEXT="Psicolog&#xed;a">
<node CREATED="1280798464482" ID="Freemind_Link_628394059" MODIFIED="1280798543108" TEXT="Estudia con inter&#xe9;s en c&#xf3;mo perciben y utilizan la informaci&#xf3;n formal los tomadores de decisiones humanas"/>
</node>
<node CREATED="1280798548309" FOLDED="true" ID="Freemind_Link_703302037" MODIFIED="1280798552866" TEXT="Econom&#xed;a">
<node CREATED="1280798553886" ID="Freemind_Link_1079543553" MODIFIED="1280798615788" TEXT="El inter&#xe9;s est&#xe1; en el impacto de los sistemas sobre el control y las estructuras al interior de la empresa y de los mercados"/>
</node>
</node>
<node CREATED="1280798028751" FOLDED="true" ID="Freemind_Link_185202029" MODIFIED="1280798040375" TEXT="No se ignora la tecnolog&#xed;a">
<node CREATED="1280798061019" ID="Freemind_Link_656993265" MODIFIED="1280798106636" TEXT="La tecnolog&#xed;a de los sistemas de informaci&#xf3;n suele ser el est&#xed;mulo para un problema  o aspecto conductual"/>
</node>
<node CREATED="1280798109855" FOLDED="true" ID="Freemind_Link_1144107456" MODIFIED="1280798125410" TEXT="Este enfoque no se concentra en las soluciones t&#xe9;cnicas">
<node CREATED="1280798135322" ID="Freemind_Link_140016497" MODIFIED="1280798175619" TEXT="Lo hace en los cambios de actitud, pol&#xed;ticas administrativas y de organizaci&#xf3;n y en el comportamiento"/>
</node>
</node>
</node>
<node CREATED="1280798741437" FOLDED="true" ID="Freemind_Link_1055646693" MODIFIED="1280798753700" TEXT="Sistemas Sociot&#xe9;cnicos">
<node CREATED="1280798765757" FOLDED="true" ID="Freemind_Link_1778932601" MODIFIED="1280798781250" TEXT="Sistemas de Informaci&#xf3;n Gerencial (MIS)">
<node CREATED="1280798787308" ID="Freemind_Link_518448256" MODIFIED="1280798822052" TEXT="El estudio de sistemas de informaci&#xf3;n que se enfoca en su uso en negocios y administraci&#xf3;n"/>
<node CREATED="1280798863429" ID="Freemind_Link_343664008" MODIFIED="1280798913358" TEXT="Surgi&#xf3; para enfocarse en los sistemas de informaci&#xf3;n basados en computadoras dirigidos a los gerentes"/>
<node CREATED="1280798929760" ID="Freemind_Link_111133883" MODIFIED="1280799084904" TEXT="MIS combina el trabajo te&#xf3;rico de las ciencias de la computaci&#xf3;n, las ciencias de la administraci&#xf3;n y la investigaci&#xf3;n de operaciones con una orientaci&#xf3;n pr&#xe1;ctica a desarrollar soluciones de sistemas a problemas del mundo real y administrar los recursos de tecnolog&#xed;a de la informaci&#xf3;n"/>
<node CREATED="1280799125189" ID="Freemind_Link_1646226087" MODIFIED="1280799213471" TEXT="Tambi&#xe9;n presta atenci&#xf3;n a aspectos conductuales que circundan el desarrollo, uso e impacto de los sistemas de informaci&#xf3;n promovidos por la sociolog&#xed;a, la econom&#xed;a y la psicolog&#xed;a"/>
</node>
<node CREATED="1280799267781" ID="Freemind_Link_1077973406" MODIFIED="1280799329637" TEXT="Adoptar una perspectiva de sistemas sociot&#xe9;cnicos ayuda a evitar un enfoque puramente tecnol&#xf3;gico para los sistemas de informaci&#xf3;n"/>
<node CREATED="1280799670456" ID="Freemind_Link_1548556675" MODIFIED="1280799688600" TEXT="Tanto los aspectos t&#xe9;cnicos como los conductuales necesitan atenci&#xf3;n"/>
<node CREATED="1280799699464" ID="Freemind_Link_1662622911" MODIFIED="1280799756757" TEXT="La tecnolog&#xed;a debe cambiar y dise&#xf1;ar de tal manera que se ajuste a las necesidades individuales y organizacionales"/>
<node CREATED="1280799780194" ID="Freemind_Link_1008112131" MODIFIED="1280799833938" TEXT="En ocasiones, la tecnolog&#xed;a se debe &quot;desoptimizar&quot; para que se cumpla dicho ajuste"/>
<node CREATED="1280799837266" ID="Freemind_Link_43488463" MODIFIED="1280799927936" TEXT="Las organizaciones y las personas tambi&#xe9;n deben cambiar mediante capacitaci&#xf3;n, aprendizaje y el cambio organizacional planeado con el prop&#xf3;sito de que la tecnolog&#xed;a pueda funcionar y prosperar"/>
<node CREATED="1280799928940" ID="Freemind_Link_1796859974" MODIFIED="1280799973932" TEXT="La gente y las organizaciones cambian para aprovechar la nueva tecnolog&#xed;a de la informaci&#xf3;n"/>
</node>
</node>
<node CREATED="1280807295581" FOLDED="true" ID="Freemind_Link_1463809904" MODIFIED="1280842909882" TEXT="Hacia la empresa digital: el nuevo rol de los sistemas de informaci&#xf3;n en la organizaciones">
<icon BUILTIN="full-3"/>
<node CREATED="1280807443709" ID="Freemind_Link_227285008" MODIFIED="1280807492352" TEXT="Los gerentes no pueden ignorar los sistemas de informaci&#xf3;n porque juegan un papel cr&#xed;tico en las organizaciones comtempor&#xe1;neas"/>
<node CREATED="1280807525414" ID="Freemind_Link_1900052828" MODIFIED="1280807605007" TEXT="Los sistemas de hoy afectan directamente la forma en que los gerentes deciden, planean y administran a sus empleados; y cada vez determinan m&#xe1;s qu&#xe9;, d&#xf3;nde, cu&#xe1;ndo y c&#xf3;mo se elaboran los productos"/>
<node CREATED="1280807608523" ID="Freemind_Link_1016774554" MODIFIED="1280807641316" TEXT="La responsabilidad sobre los sistemas no se puede delegar en los tomadores de decisiones t&#xe9;cnicos"/>
<node CREATED="1280807661633" FOLDED="true" ID="Freemind_Link_1898101943" MODIFIED="1390920008935" TEXT="Creciente alcance de los sistemas de informaci&#xf3;n">
<node CREATED="1280807716756" ID="Freemind_Link_1718881659" MODIFIED="1280807799282" TEXT="Hay una creciente interdependencia entre la estrategia de negocios, las reglas y los procedimientos y por otro entre el software, el hardware, bases de datos y telecomunicaciones de los sistemas de informaci&#xf3;n"/>
<node CREATED="1280807820067" ID="Freemind_Link_992916495" MODIFIED="1280807883139" TEXT="Un cambio en algunos de estos componentes requiere cambios en otros componentes"/>
<node CREATED="1280807938510" ID="Freemind_Link_941223095" MODIFIED="1280808018228" TEXT="Un segundo cambio en la relaci&#xf3;n entre los sistemas de informaci&#xf3;n y las organizaciones resulta del crecimiento del alcance y el &#xe1;mbito de los proyectos y aplicaciones del sistema"/>
<node CREATED="1280808038279" ID="Freemind_Link_1074390431" MODIFIED="1280808113926" TEXT="Actualmente, el establecimiento y administraci&#xf3;n de los sistemas involucra una parte mucho m&#xe1;s grande de la organizaci&#xf3;n de lo que se hac&#xed;a en el pasado"/>
<node CREATED="1280808233190" ID="Freemind_Link_626334454" MODIFIED="1280808308066" TEXT="A medida de las empresas se transforman m&#xe1;s en &quot;empresas digitales&quot; el sistema extiende a los clientes, proveedores e incluso a los competidores de la industria"/>
</node>
<node CREATED="1280808392651" FOLDED="true" ID="Freemind_Link_454123711" MODIFIED="1390920008938" TEXT="La revoluci&#xf3;n de las redes e Internet">
<node CREATED="1280808458657" ID="Freemind_Link_472286155" MODIFIED="1280808532091" TEXT="Una raz&#xf3;n de que los sistemas de informaci&#xf3;n jueguen un rol tan importante en las organizaciones y que afecten a tanta gente es la creciente potencia y la baja de costos de la tecnolog&#xed;a de c&#xf3;mputo"/>
<node CREATED="1280808627358" ID="Freemind_Link_1576308746" MODIFIED="1280808751934" TEXT="La creciente potencia de la tecnolog&#xed;a de c&#xf3;mputo ha dado origen a redes de comunicaciones potentes que las empresas pueden utilizar para tener acceso a inmensos almacenes de informaci&#xf3;n de todo el mundo y coordinar actividades m&#xe1;s all&#xe1; del tiempo y el espacio"/>
<node CREATED="1280808778820" FOLDED="true" ID="Freemind_Link_979556486" MODIFIED="1390920008936" TEXT="Internet">
<node CREATED="1280808783685" ID="Freemind_Link_1816506834" MODIFIED="1280808816052" TEXT="Red de redes internacional que es un conjunto de cientos de miles de redes p&#xfa;blicas y comerciales"/>
<node CREATED="1280808934323" ID="Freemind_Link_252189087" MODIFIED="1280808965882" TEXT="Inspira nuevos usos de los sistemas de informaci&#xf3;n y nuevos modelos de negocios"/>
<node CREATED="1280808975200" ID="Freemind_Link_575523576" MODIFIED="1280809006326" TEXT="Proporciona la plataforma primaria de tecnolog&#xed;a para la empresa digital"/>
</node>
<node CREATED="1280809035850" FOLDED="true" ID="Freemind_Link_121040428" MODIFIED="1390920008937" TEXT="World Wide Web">
<node CREATED="1280809047143" ID="Freemind_Link_998608976" MODIFIED="1280809101077" TEXT="Un sistema con est&#xe1;ndares aceptados universalmente para almacenar, recuperar, formar y desplegar informaci&#xf3;n en un entorno conectado en redes"/>
</node>
<node CREATED="1280809144612" FOLDED="true" ID="Freemind_Link_1104700317" MODIFIED="1390920008938" TEXT="Sitio Web">
<node CREATED="1280809151621" ID="Freemind_Link_654917625" MODIFIED="1280809186722" TEXT="Todas las p&#xe1;ginas de la World Wide Web mantenidas por una organizaci&#xf3;n o un individuo"/>
</node>
</node>
<node CREATED="1280809230878" ID="Freemind_Link_1945941618" MODIFIED="1280809257357" TEXT="Nuevas opciones de dise&#xf1;o de la organizaci&#xf3;n: la empresa digital y la empresa colaborativa"/>
</node>
